#include <stdio.h>

int main() {
    int pageTable[10];  // Array representing a small linear page table
    for(int i = 0; i < 10; i++) {
        pageTable[i] = i;  // Initialize each entry with a simple value
    }
    printf("Page table entry 0: %d\n", pageTable[0]);  // Access and print an entry
    return 0;
}
